cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums and fee", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("single sword, newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("amulet base premium 60 G (newcomer: 60 + 6 + 5 = 71 G)");
    it.todo("staff base premium 80 G (newcomer: 80 + 8 + 5 = 93 G)");
    it.todo("potion base premium 40 G (newcomer: 40 + 4 + 5 = 49 G)");
  });

  describe("quote — components and blocks of 3 alike", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword adds 50 % of its base premium (newcomer: 100 + 50 + 10 + 5 = 165 G)");
    it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("cursed sword + plain amulet → surcharge applies only to the cursed sword's base (210 G before policy modifiers and fee)");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount 20 % applies");
    it.todo("customer with 1 year → no loyalty discount");
    it.todo("second quote in the scenario → 15 % follow-up discount, first insurance surcharge still applies");
    it.todo("premium yielding 197.5 G → rounded up to 198 G");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer with a cursed sword (steel, enchantment 3) → 165 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G (no special clause)");
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible once per damaged item)");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("payout yielding 350.5 G → rounded down to 350 G");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("sword + amulet → remainingCap 3200 G after a zero-damage claim (insurance sum 1600 G)");
    it.todo("cursed sword → cap 2000 G (modifiers do not raise the cap)");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
    it.todo("two swords → cap 4000 G; two sword damages each get their own deductible");
    it.todo("two successive 1500 G claims on a sword → 1400 G (cap 600 left), then 600 G (cap 0)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → throws an error");
    it.todo("claim for an item not in the policy (amulet when only sword insured) → throws an error");
    it.todo("claim with more damages of a type than insured (two sword damages, one sword) → throws an error");
    it.todo("claim with negative damage amount → throws an error");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes {results: [...]} to stdout");
    it.todo("unknown item type → non-zero exit, error on stderr, nothing on stdout");
  });
});
EOF
