const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

// Exactly three alike items form a discounted block; any other count is priced per item.
const alikeItemsPremium = (type: string, count: number): number =>
  count === ALIKE_BLOCK_SIZE
    ? ALIKE_BLOCK_PREMIUM
    : count * BASE_PREMIUM_BY_TYPE[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (sum, [type, count]) => sum + alikeItemsPremium(type, count),
    0,
  );

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  const basePremium = policyBasePremium(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const premium = roundPremiumInFavorOfMHPCO(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
  return { results: [{ premium }] };
};

