const curseSurcharge = (items: Item[]): number =>
  items
    .filter((item) => item.cursed)
    .reduce(
      (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type] * CURSE_SURCHARGE_RATE,
      0,
    );

const quotePremium = (items: Item[]): number => {
  const basePremium = policyBasePremium(items);
  // Policy-wide modifiers apply to the policy base premium.
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return roundPremiumInFavorOfMHPCO(
    basePremium + curseSurcharge(items) + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(step.items) }] };
};

