const damagePayout = (damage: Damage, insuredItems: Item[]): number => {
  const insuredItem = insuredItems.find((item) => item.type === damage.itemType);
  const reimbursementRate =
    (insuredItem?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
      ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
      : 1;
  return damage.amount * reimbursementRate - DEDUCTIBLE;
};

const claimPayout = (damages: Damage[], insuredItems: Item[]): number =>
  damages.reduce((sum, damage) => sum + damagePayout(damage, insuredItems), 0);

const settleClaim = (step: ClaimStep, steps: Step[]): ClaimResult => {
