const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + PRICE_LIST[item.type].insuranceValue, 0);

const settleClaim = (step: ClaimStep, steps: Step[]): ClaimResult => {
  const policy = steps[step.policy] as QuoteStep;
  const payout = roundPayoutInFavorOfMHPCO(
    claimPayout(step.incident.damages, policy.items),
  );
  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
  return { payout, remainingCap: cap - payout };
};

const issueQuote = (
  step: QuoteStep,
  yearsWithMHPCO: number,
  isFollowUpContract: boolean,
): QuoteResult => ({
  premium: quotePremium(step.items, yearsWithMHPCO, isFollowUpContract),
});

// Every contract after the customer's first one in the scenario is a follow-up.
const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const { yearsWithMHPCO } = scenario.customer;
  const results = scenario.steps.map((step, index): StepResult =>
    step.op === "claim"
      ? settleClaim(step, scenario.steps)
      : issueQuote(step, yearsWithMHPCO, isFollowUpContract(index)),
  );
  return { results };
};

